use ota_agent::hex;
use ota_agent::sha256::digest;
use ota_agent::{parse_manifest, verify_update, DeviceState, ManifestError, Version, VerifyError};

fn image() -> Vec<u8> {
    (0..3000u32).map(|i| (i % 256) as u8).collect()
}

fn manifest_text(img: &[u8], version: &str) -> String {
    format!(
        "# generated by ota-backend 2.14\nformat = 1\ncomponent = tcu-main\nversion = {version}\nimage_size = {}\nimage_sha256 = {}\n",
        img.len(),
        hex::encode(&digest(img))
    )
}

fn device() -> DeviceState {
    DeviceState::new("tcu-main", Version::new(5, 2, 0))
}

#[test]
fn parses_format1() {
    let img = image();
    let m = parse_manifest(&manifest_text(&img, "5.3.1")).unwrap();
    assert_eq!(m.format, 1);
    assert_eq!(m.component, "tcu-main");
    assert_eq!(m.version, Version::new(5, 3, 1));
    assert_eq!(m.image_size, 3000);
    assert_eq!(m.image_sha256, digest(&img));
}

#[test]
fn whitespace_comments_and_unknown_keys() {
    let img = image();
    let text = format!("\n  # comment\n{}  release_notes =  fixes  \n\n", manifest_text(&img, "5.3.1"));
    assert!(parse_manifest(&text).is_ok());
}

#[test]
fn parse_errors() {
    let img = image();
    let good = manifest_text(&img, "5.3.1");
    assert_eq!(
        parse_manifest(&good.replace("component = tcu-main\n", "")),
        Err(ManifestError::MissingKey("component".into()))
    );
    assert_eq!(
        parse_manifest(&format!("{good}component = other\n")),
        Err(ManifestError::DuplicateKey("component".into()))
    );
    assert_eq!(parse_manifest("format = 1\nthis line is broken\n"), Err(ManifestError::Syntax { line: 2 }));
    assert_eq!(parse_manifest(&good.replace("format = 1", "format = 9")), Err(ManifestError::UnsupportedFormat(9)));
    assert!(matches!(
        parse_manifest(&good.replace("version = 5.3.1", "version = 5.3")),
        Err(ManifestError::InvalidValue { .. })
    ));
    assert!(matches!(
        parse_manifest(&good.replace("image_size = 3000", "image_size = -1")),
        Err(ManifestError::InvalidValue { .. })
    ));
}

#[test]
fn verifies_good_image() {
    let img = image();
    let m = parse_manifest(&manifest_text(&img, "5.3.1")).unwrap();
    let ok = verify_update(&m, &img, &device()).unwrap();
    assert_eq!(ok.component, "tcu-main");
    assert_eq!(ok.version, Version::new(5, 3, 1));
}

#[test]
fn rejects_wrong_component() {
    let img = image();
    let m = parse_manifest(&manifest_text(&img, "5.3.1")).unwrap();
    let dev = DeviceState::new("tcu-modem", Version::new(1, 0, 0));
    assert!(matches!(verify_update(&m, &img, &dev), Err(VerifyError::ComponentMismatch { .. })));
}

#[test]
fn rejects_truncated_and_corrupt() {
    let img = image();
    let m = parse_manifest(&manifest_text(&img, "5.3.1")).unwrap();
    assert_eq!(
        verify_update(&m, &img[..2999], &device()),
        Err(VerifyError::SizeMismatch { expected: 3000, actual: 2999 })
    );
    let mut bad = img.clone();
    bad[1234] ^= 0x40;
    assert_eq!(verify_update(&m, &bad, &device()), Err(VerifyError::ImageDigestMismatch));
}
